'use client';

import { useEffect, useMemo, useState } from 'react';
import AppShell from '@/components/Navbar';
import { api } from '@/lib/api';

interface AuditLogItem {
  id: number;
  actor_id: number | null;
  action: string;
  target_table: string;
  target_id: number | null;
  details: string | null;
  performed_at: string;
}

interface AuditResponse {
  success: boolean;
  message: string;
  data: AuditLogItem[];
  meta: { total: number; page: number; per_page: number };
}

export default function AuditLogPage() {
  const [rows, setRows] = useState<AuditLogItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [meta, setMeta] = useState({ total: 0, page: 1, per_page: 20 });
  const [action, setAction] = useState('');
  const [targetTable, setTargetTable] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [search, setSearch] = useState('');

  useEffect(() => {
    (async () => {
      try {
        setLoading(true);
        setError(null);
        const qs = new URLSearchParams({ page: String(page) });
        if (action) qs.set('action', action);
        if (targetTable) qs.set('target_table', targetTable);
        if (fromDate) qs.set('from_date', fromDate);
        if (toDate) qs.set('to_date', toDate);
        const res = await api.get<AuditResponse>(`/admin/audit-log?${qs.toString()}`);
        setRows(res.data ?? []);
        setMeta(res.meta ?? { total: 0, page, per_page: 20 });
      } catch (e) {
        setError(e instanceof Error ? e.message : 'Failed to load audit logs.');
      } finally {
        setLoading(false);
      }
    })();
  }, [page, action, targetTable, fromDate, toDate]);

  const filtered = useMemo(() => {
    if (!search.trim()) return rows;
    const q = search.toLowerCase();
    return rows.filter((r) =>
      String(r.id).includes(q) ||
      String(r.actor_id ?? '').includes(q) ||
      r.action.toLowerCase().includes(q) ||
      r.target_table.toLowerCase().includes(q) ||
      (r.details ?? '').toLowerCase().includes(q)
    );
  }, [rows, search]);

  const totalPages = Math.max(1, Math.ceil((meta.total || 0) / (meta.per_page || 20)));

  return (
    <AppShell role="admin" userName="Admin" pageTitle="Audit Log">
      <div className="space-y-4">
        <h1 className="text-[20px] font-bold">Audit Log</h1>

        <div className="card card-body grid grid-cols-1 md:grid-cols-5 gap-3">
          <input placeholder="Search in current page" value={search} onChange={(e) => setSearch(e.target.value)} />
          <input placeholder="Action (exact)" value={action} onChange={(e) => { setAction(e.target.value); setPage(1); }} />
          <input placeholder="Target table (exact)" value={targetTable} onChange={(e) => { setTargetTable(e.target.value); setPage(1); }} />
          <input type="date" value={fromDate} onChange={(e) => { setFromDate(e.target.value); setPage(1); }} />
          <input type="date" value={toDate} onChange={(e) => { setToDate(e.target.value); setPage(1); }} />
        </div>

        {error && <div className="rounded-lg border px-3 py-2 text-[12px]" style={{ borderColor: '#fecaca', background: '#fff1f2', color: '#9f1239' }}>{error}</div>}

        <div className="card overflow-hidden">
          <div className="card-body pb-2 flex items-center justify-between">
            <span className="text-[12px]" style={{ color: 'var(--color-text-muted)' }}>
              {loading ? 'Loading...' : `Showing ${filtered.length} rows (total ${meta.total})`}
            </span>
            <span className="text-[12px]" style={{ color: 'var(--color-text-muted)' }}>Page {meta.page} / {totalPages}</span>
          </div>
          <div className="overflow-x-auto">
            <table className="table-base">
              <thead>
                <tr><th>ID</th><th>Actor ID</th><th>Action</th><th>Target</th><th>Details</th><th>Performed At</th></tr>
              </thead>
              <tbody>
                {filtered.map((r) => (
                  <tr key={r.id}>
                    <td>{r.id}</td>
                    <td>{r.actor_id ?? '-'}</td>
                    <td>{r.action}</td>
                    <td>{r.target_table}{r.target_id ? ` #${r.target_id}` : ''}</td>
                    <td className="text-[12px]">{r.details ?? '-'}</td>
                    <td>{new Date(r.performed_at).toLocaleString('en-US')}</td>
                  </tr>
                ))}
                {!loading && filtered.length === 0 && <tr><td colSpan={6} className="text-center text-[12px]">No audit logs found.</td></tr>}
              </tbody>
            </table>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button className="btn btn-ghost" disabled={page <= 1} onClick={() => setPage((p) => Math.max(1, p - 1))}>Prev</button>
          <button className="btn btn-ghost" disabled={page >= totalPages} onClick={() => setPage((p) => Math.min(totalPages, p + 1))}>Next</button>
        </div>
      </div>
    </AppShell>
  );
}
